def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    vals = sorted(set(a))
    rank = {v: idx + 1 for idx, v in enumerate(vals)}
    m = len(vals)
    tree = [0] * (m + 1)

    def add(i: int, d: int) -> None:
        while i <= m:
            tree[i] += d
            i += i & -i

    def query(i: int) -> int:
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s

    res = [0] * n
    for i in range(n):
        if i >= 1:
            add(rank[a[i - 1]], 1)
        j = i - k - 1
        if j >= 0:
            add(rank[a[j]], -1)
        size = min(i, k)
        res[i] = size - query(rank[a[i]])
    return res
